def main():
    while False:
        print('while loop action')
    _cv_first_iteration = True
    while _cv_first_iteration or (False):
        _cv_first_iteration = False
        print('do-first loop action')
    for item in range(3):
        print('for loop action')
    _cv_item_work = _cv_deque([{'children': []}])
    while _cv_item_work:
        item = _cv_item_work.popleft()
