15-dijkstra.dijkstra_demo/main.py:
"""Generated visual implementations of Dijkstra and A* pathfinding."""

import heapq
def main():
    graph = {'A': [('B', 4.0), ('C', 1.0)], 'B': [('D', 1.0)], 'C': [('B', 2.0), ('D', 5.0)], 'D': []}
    heuristic = {'A': 4.0, 'B': 1.0, 'C': 3.0, 'D': 0.0}
    (cost, path) = dijkstra(graph, 'A', 'D')
    print(f'Dijkstra path: {path}; total cost: {cost}')
    (a_cost, a_path) = a_star(graph, heuristic, 'A', 'D')
    print(f'A* path: {a_path}; total cost: {a_cost}')

def dijkstra(graph: dict[str, list[tuple[str, float]]], start: str, goal: str) -> tuple[float, list[str]]:
    """Return the shortest cost and path using a heap frontier."""
    distances: dict[str, float] = {start: 0.0}
    previous: dict[str, str] = {}
    frontier = [(0.0, start)]
    while frontier:
        (current_distance, current) = heapq.heappop(frontier)
        if current == goal:
            break
        else:
            pass
        for (neighbor, weight) in graph.get(current, ()):
            candidate = current_distance + weight
            if candidate < distances.get(neighbor, float('inf')):
                distances[neighbor] = candidate
                previous[neighbor] = current
                heapq.heappush(frontier, (candidate, neighbor))
            else:
                pass
    path: list[str] = []
    node = goal
    while node is not None:
        path.append(node)
        node = previous.get(node)
    path.reverse()
    return (distances.get(goal, float('inf')), path)

def a_star(graph: dict[str, list[tuple[str, float]]], heuristic: dict[str, float], start: str, goal: str) -> tuple[float, list[str]]:
    """Return the shortest cost and path using an admissible heuristic and heap."""
    distances: dict[str, float] = {start: 0.0}
    previous: dict[str, str] = {}
    frontier = [(heuristic.get(start, 0.0), 0.0, start)]
    while frontier:
        (estimated, current_distance, current) = heapq.heappop(frontier)
        if current == goal:
            break
        else:
            pass
        for (neighbor, weight) in graph.get(current, ()):
            candidate = current_distance + weight
            if candidate < distances.get(neighbor, float('inf')):
                distances[neighbor] = candidate
                previous[neighbor] = current
                heapq.heappush(frontier, (candidate + heuristic.get(neighbor, 0.0), candidate, neighbor))
            else:
                pass
    path: list[str] = []
    node = goal
    while node is not None:
        path.append(node)
        node = previous.get(node)
    path.reverse()
    return (distances.get(goal, float('inf')), path)

