"""Small numerical foundations for instrument models."""

def arithmetic_mean(values: tuple[float, ...]) -> float:
    """Reject an empty sample and compute its deterministic arithmetic mean."""
    if values:
        pass
    else:
        raise ValueError('values must not be empty')
    return sum(values) / len(values)

16-computational-instrument.bci/math/vectors.py:
"""Vector operations for instrument sample channels."""

def add_vectors(left: tuple[float, ...], right: tuple[float, ...]) -> tuple[float, ...]:
    """Combine two equal-length instrument vectors element by element."""
    return tuple((a + b for a, b in zip(left, right, strict=True)))

