"""Stable model snapshots shared across subsystem boundaries."""

from bci.math.numerical import arithmetic_mean
def make_snapshot(samples: tuple[float, ...]) -> dict[str, object]:
    """Create an immutable-style model snapshot from instrument samples."""
    average = arithmetic_mean(samples)
    return {'samples': samples, 'mean': average}

